mod debug_assert {
    use std::fmt;

    pub trait DefaultHandler {}

    pub trait Level {
        fn level() -> u32;
    }

    pub struct SetLevel<const L: u32>;
    impl<const L: u32> Level for SetLevel<L> {
        fn level() -> u32 {
            L
        }
    }

    pub struct SourceLocation {
        pub file_name: &'static str,
        pub line_number: u32,
    }

    impl fmt::Display for SourceLocation {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "{}:{}", self.file_name, self.line_number)
        }
    }

    pub fn assert(condition: bool, loc: SourceLocation, expression: &str) {
        if !condition {
            std::panic::panic_any(format!(
                "Assertion failed: '{}', at {}",
                expression, loc
            ));
        }
    }

    pub fn unreachable(loc: SourceLocation) -> ! {
        panic!("Reached unreachable code at {}", loc);
    }

    #[macro_export]
    macro_rules! debug_assert {
        ($cond:expr, $module:ty $(, $extra:expr)*) => {{
            let loc = debug_assert::SourceLocation {
                file_name: file!(),
                line_number: line!(),
            };
            let level = <$module as debug_assert::Level>::level();
            if level >= 1 {
                debug_assert::assert($cond, loc, stringify!($cond));
            }
        }};
    }

    #[macro_export]
    macro_rules! debug_unreachable {
        ($module:ty) => {{
            let loc = debug_assert::SourceLocation {
                file_name: file!(),
                line_number: line!(),
            };
            let level = <$module as debug_assert::Level>::level();
            if level >= 1 {
                debug_assert::unreachable(loc);
            }
        }};
    }
}

use std::ffi::c_void;

//=== module A ===//
const MODULE_A_LEVEL: u32 = 1;

struct ModuleA;

impl debug_assert::DefaultHandler for ModuleA {}
impl debug_assert::Level for ModuleA {
    fn level() -> u32 {
        MODULE_A_LEVEL
    }
}

fn module_a_func(ptr: Option<&mut c_void>) {
    debug_assert!(ptr.is_some(), ModuleA);
    debug_assert!(2 + 2 == 4, ModuleA);
    debug_assert!(1 == 0, ModuleA, "this should be true");
    debug_unreachable!(ModuleA);
}

//=== module B ===//
const MODULE_B_LEVEL: u32 = 2;

struct ModuleB;

impl debug_assert::Level for ModuleB {
    fn level() -> u32 {
        MODULE_B_LEVEL
    }
}

impl ModuleB {
    fn handle(loc: debug_assert::SourceLocation, expression: &str, ptr: Option<*const c_void>) {
        eprintln!("Assertion failure '{}' at {}: {}", expression, loc.file_name, loc.line_number);
        if let Some(ptr_value) = ptr {
            eprintln!(" - pointer is {:?}", ptr_value);
        }
    }
}

fn module_b_func(value: &mut i32, ptr: Option<&mut c_void>) {
    debug_assert!(ptr.as_ref().map_or(false, |p| *p as *const c_void == value as *const i32 as *const c_void), ModuleB, ptr);
    debug_assert!(ptr.as_ref().map_or(false, |p| *p as *const c_void == value as *const i32 as *const c_void), ModuleB);
}

fn main() {
    module_a_func(None);
    let mut val = 5;
    let ptr: *mut c_void = &mut val as *mut _ as *mut c_void;
    module_b_func(&mut val, Some(unsafe { &mut *ptr }));
}

